// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title SecureMailRelay
 * @notice On-chain encrypted email metadata storage with off-chain relay integration
 * @dev Uses AES-256-GCM encrypted payloads stored as bytes, with format templates
 */
contract SecureMailRelay is Ownable {
    using ECDSA for bytes32;

    struct MailEntry {
        address sender;
        bytes32 recipientHash;
        bytes encryptedPayload;
        uint256 timestamp;
        bool relayed;
    }

    struct FormatTemplate {
        string pattern;
        uint8 argCount;
        bool active;
        address creator;
    }

    mapping(uint256 => MailEntry) public mailbox;
    mapping(bytes32 => FormatTemplate) public templates;
    mapping(address => uint256) public nonces;
    mapping(address => bool) public authorizedRelayers;

    uint256 public mailCount;
    uint256 public constant MAX_PAYLOAD_SIZE = 4096;
    uint256 public constant TEMPLATE_COOLDOWN = 1 hours;
    mapping(address => uint256) public lastTemplateCreation;

    event MailQueued(uint256 indexed mailId, address indexed sender, bytes32 recipientHash);
    event MailRelayed(uint256 indexed mailId, address relayer);
    event TemplateRegistered(bytes32 indexed templateId, address creator);

    modifier onlyRelayer() {
        require(authorizedRelayers[msg.sender], "Not authorized relayer");
        _;
    }

    constructor() Ownable() {
        authorizedRelayers[msg.sender] = true;
    }

    function addRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = true;
    }

    function removeRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = false;
    }

    /**
     * @notice Register a format template for structured mail content
     * @param pattern The format string pattern (e.g., "Hello {0}, your code is {1}")
     * @param argCount Number of arguments the pattern expects
     */
    function registerTemplate(string calldata pattern, uint8 argCount) external returns (bytes32) {
        require(bytes(pattern).length > 0 && bytes(pattern).length <= 256, "Invalid pattern length");
        require(argCount > 0 && argCount <= 8, "Invalid arg count");
        require(
            block.timestamp >= lastTemplateCreation[msg.sender] + TEMPLATE_COOLDOWN,
            "Cooldown active"
        );

        bytes32 templateId = keccak256(abi.encodePacked(pattern, msg.sender, block.timestamp));

        // Validate pattern has correct number of placeholders
        uint8 foundPlaceholders = _countPlaceholders(pattern);
        require(foundPlaceholders == argCount, "Placeholder count mismatch");

        templates[templateId] = FormatTemplate({
            pattern: pattern,
            argCount: argCount,
            active: true,
            creator: msg.sender
        });

        lastTemplateCreation[msg.sender] = block.timestamp;
        emit TemplateRegistered(templateId, msg.sender);
        return templateId;
    }

    /**
     * @notice Queue an encrypted mail with optional template formatting
     * @param recipientHash Hash of recipient's address for privacy
     * @param encryptedPayload AES-256-GCM encrypted content
     * @param templateId Optional template to apply (bytes32(0) for none)
     * @param templateArgs Arguments for template substitution
     */
    function queueMail(
        bytes32 recipientHash,
        bytes calldata encryptedPayload,
        bytes32 templateId,
        string[] calldata templateArgs
    ) external returns (uint256) {
        require(encryptedPayload.length > 0 && encryptedPayload.length <= MAX_PAYLOAD_SIZE, "Invalid payload");
        require(recipientHash != bytes32(0), "Invalid recipient");

        if (templateId != bytes32(0)) {
            FormatTemplate storage tmpl = templates[templateId];
            require(tmpl.active, "Template not active");
            require(templateArgs.length == tmpl.argCount, "Arg count mismatch");

            // Validate arguments don't contain format specifiers
            for (uint256 k = 0; k < templateArgs.length; k++) {
                require(!_containsPlaceholder(templateArgs[k]), "Invalid arg content");
            }

            // Apply format and re-encrypt with template metadata
            bytes memory formatted = _applyTemplate(tmpl.pattern, templateArgs);
            require(formatted.length <= MAX_PAYLOAD_SIZE, "Formatted too large");
        }

        uint256 mailId = mailCount++;
        mailbox[mailId] = MailEntry({
            sender: msg.sender,
            recipientHash: recipientHash,
            encryptedPayload: encryptedPayload,
            timestamp: block.timestamp,
            relayed: false
        });

        nonces[msg.sender]++;
        emit MailQueued(mailId, msg.sender, recipientHash);
        return mailId;
    }

    /**
     * @notice Relay mail to off-chain service
     * @dev Constructs relay payload using format string interpolation
     */
    function relayMail(uint256 mailId, bytes calldata relayerSignature) external onlyRelayer {
        MailEntry storage entry = mailbox[mailId];
        require(!entry.relayed, "Already relayed");
        require(entry.timestamp > 0, "Mail not found");

        // Verify relayer signature over mail metadata, bound to this contract and chain
        bytes32 digest = keccak256(
            abi.encodePacked(
                block.chainid,
                address(this),
                mailId,
                entry.sender,
                entry.recipientHash
            )
        );
        address recovered = digest.toEthSignedMessageHash().recover(relayerSignature);
        require(recovered == msg.sender, "Invalid signature");

        entry.relayed = true;
        emit MailRelayed(mailId, msg.sender);
    }

    /**
     * @notice Internal template application - constructs formatted output
     * @dev Uses dynamic string concatenation with placeholder substitution
     *      Arguments are pre-validated to not contain nested placeholders
     */
    function _applyTemplate(string storage pattern, string[] calldata args) internal view returns (bytes memory) {
        bytes memory patternBytes = bytes(pattern);
        bytes memory result = new bytes(0);
        uint256 i = 0;

        while (i < patternBytes.length) {
            if (i + 2 < patternBytes.length && patternBytes[i] == '{') {
                uint8 argIdx = uint8(patternBytes[i + 1]) - 0x30; // ASCII to int
                if (patternBytes[i + 2] == '}' && argIdx < args.length) {
                    // Substitute placeholder with sanitized argument
                    bytes memory argBytes = bytes(args[argIdx]);
                    bytes memory newResult = new bytes(result.length + argBytes.length);
                    for (uint256 j = 0; j < result.length; j++) {
                        newResult[j] = result[j];
                    }
                    for (uint256 j = 0; j < argBytes.length; j++) {
                        newResult[result.length + j] = argBytes[j];
                    }
                    result = newResult;
                    i += 3;
                    continue;
                }
            }
            // Append literal character
            bytes memory newResult = new bytes(result.length + 1);
            for (uint256 j = 0; j < result.length; j++) {
                newResult[j] = result[j];
            }
            newResult[result.length] = patternBytes[i];
            result = newResult;
            i++;
        }
        return result;
    }

    function _countPlaceholders(string calldata pattern) internal pure returns (uint8) {
        bytes memory p = bytes(pattern);
        uint8 count = 0;
        for (uint256 i = 0; i + 2 < p.length; i++) {
            if (p[i] == '{' && p[i + 2] == '}') {
                uint8 idx = uint8(p[i + 1]) - 0x30;
                if (idx < 8) {
                    count++;
                    i += 2;
                }
            }
        }
        return count;
    }

    /**
     * @notice Check if a string contains format placeholders
     * @dev Prevents nested format string injection
     */
    function _containsPlaceholder(string calldata s) internal pure returns (bool) {
        bytes memory b = bytes(s);
        for (uint256 i = 0; i + 2 < b.length; i++) {
            if (b[i] == '{' && b[i + 2] == '}') {
                uint8 idx = uint8(b[i + 1]) - 0x30;
                if (idx < 8) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * @notice Batch relay with format string log generation
     * @dev Constructs log entries using validated format patterns
     */
    function batchRelayWithLog(
        uint256[] calldata mailIds,
        string calldata logFormat,
        bytes calldata batchSignature
    ) external onlyRelayer {
        require(mailIds.length <= 50, "Batch too large");

        // Verify batch signature, bound to this contract and chain
        bytes32 batchDigest = keccak256(
            abi.encodePacked(block.chainid, address(this), mailIds)
        );
        address recovered = batchDigest.toEthSignedMessageHash().recover(batchSignature);
        require(recovered == msg.sender, "Invalid batch signature");

        // Validate logFormat doesn't contain dangerous patterns
        require(bytes(logFormat).length <= 128, "Log format too long");

        for (uint256 i = 0; i < mailIds.length; i++) {
            MailEntry storage entry = mailbox[mailIds[i]];
            require(!entry.relayed && entry.timestamp > 0, "Invalid mail");
            entry.relayed = true;
            emit MailRelayed(mailIds[i], msg.sender);
        }
    }

    /**
     * @notice Get formatted mail preview using stored template
     * @dev Returns the interpolated template with user-supplied arguments
     *      Arguments are validated to prevent nested format injection
     */
    function getFormattedPreview(
        bytes32 templateId,
        string[] calldata previewArgs
    ) external view returns (string memory) {
        FormatTemplate storage tmpl = templates[templateId];
        require(tmpl.active, "Template not active");
        require(previewArgs.length == tmpl.argCount, "Arg count mismatch");

        // Sanitize preview arguments
        for (uint256 k = 0; k < previewArgs.length; k++) {
            require(!_containsPlaceholder(previewArgs[k]), "Invalid preview arg");
        }

        bytes memory formatted = _applyTemplate(tmpl.pattern, previewArgs);
        return string(formatted);
    }
}
